import React, { useEffect, useRef, useState } from "react";

const dpr = 1 || window.devicePixelRatio;
const height = window.innerHeight * 0.6;
const width = window.innerWidth;

export default function DrawCircle() {
  const [, forceUpdate] = useState({})
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const ctxRef = useRef<CanvasRenderingContext2D | null>(null);

  let best = 0;


  useEffect(() => {
    if (canvasRef.current) {
      ctxRef.current = canvasRef.current?.getContext('2d') ?? null;
      const ctx = ctxRef.current!;
      const canvas = canvasRef.current!;
      drawGrid(canvasRef.current);
      drawCenter(canvas);

      /** canvas元素左上角的clientx */
      const originClientX = canvas.getBoundingClientRect().left;
      /** canvas元素左上角的clienty */
      const originClientY = canvas.getBoundingClientRect().top;

      /** canvas中点x（相对canvas） */
      const canvasCenterX = canvas.width / 2;
      /** canvas中点y（相对canvas） */
      const canvasCenterY = canvas.height / 2;

      let paths: { points: { x: number, y: number }[] }[] = []; // 用于保存绘制的路径

      // 清除特定路径的绘制(会清除整个画布)
      function clearPath(pathIndex: number, drawOthersContent?: () => void) {
        if (pathIndex >= 0 && pathIndex < paths.length) {
          const path = paths[pathIndex];
          ctx.clearRect(0, 0, canvas.width, canvas.height); // 清除整个画布
          drawOthersContent?.();
          // 重新绘制其他路径
          paths.filter((_, index) => index !== pathIndex).forEach((p) => {
            ctx.beginPath();
            ctx.moveTo(p.points[0].x, p.points[0].y);
            p.points.slice(1).forEach((point) => {
              ctx.lineTo(point.x, point.y);
            });
            ctx.stroke();
          });
        }
      }


      // 监听画圆
      canvas.addEventListener('mousedown', (e) => {
        // hiddenError();
        paths.map((v, index) => {
          clearPath(index, () => {// M每次绘制之前，清空画布，并重新画grid和中心圆点
            drawGrid(canvas);
            drawCenter(canvas)
          });

        });
        /** 起点x */
        const startX = e.clientX - originClientX;
        /**起点Y */
        const startY = e.clientY - originClientY;

        paths = [];// 路径坐标（相对canvas坐标原点）

        /** 由第一个点确定的圆心 */
        let circle_r = calculateDistance(canvasCenterX, canvasCenterY, startX, startY);

        if (circle_r < 80) {
          showTopAndBottomText(' ', '太小啦,画个大点的圆吧');
          return;
        }

        const distance = [circle_r]; // 每个点距离圆心的距离
        /** 当前路径，∠起点，圆心，终点的角度 */
        let currentAngle = 0;

        /** 固定一个点，如果是圆周运动，则以这个固定点为起点，每次移动，它的角度都是在增加的 */
        let latestAngleStart = {
          x: startX,
          y: startY,
        }
        /** 当前点的上一个点到latestAngleStart的角度，latestAngleStart重置的时候，这个也要重置 */
        let latestAngle = 0;
        let AngleCount = 0;

        const path: { points: { x: number, y: number }[] } = { points: [] };
        paths.push(path);


        ctx.beginPath();

        path.points.push({
          x: startX,
          y: startY,
        })
        ctx.moveTo(startX, startY);

        canvas.addEventListener('mousemove', onMouseMove);
        canvas.addEventListener('mouseup', onMouseUp);

        function onMouseMove(e: MouseEvent) {
          ctx.lineWidth = 4;
          const dotx = e.clientX - originClientX;
          const doty = e.clientY - originClientY;
          const latsetPoiot = path.points.slice(-1);

          if (path.points.length && path.points.length % 10 === 0) {
            ctx.beginPath();



            ctx.moveTo(latsetPoiot[0].x, latsetPoiot[0].y);

            // 检查是否错误路径
            if (path.points.length % 10 === 0) {
              AngleCount += latestAngle;
              console.log('===AngleCount', AngleCount)
              // 每隔10个点设置检查一个基准点
              latestAngle = 0;
              latestAngleStart = {
                x: latsetPoiot[0].x,
                y: latsetPoiot[0].y
              }
            }


            ctx.strokeStyle = '#' + Math.random().toString(16).slice(-6);
          }

          // 计算距离圆心
          const a1 = calculateDistance(canvasCenterX, canvasCenterY, dotx, doty);
          distance.push(a1);

          // 检查是否错误路径
          if (path.points.length % 3 === 0) {
            // 每3个点检查一下：当前点的角度和上一个检查点的角度相比，是不是增加的
            const currentAngleBaseLatestStart = calculateAngle(dotx, doty, canvasCenterX, canvasCenterY, latestAngleStart.x, latestAngleStart.y);
            if (currentAngleBaseLatestStart < latestAngle) {
              console.log('====错误路径', {// TODO 做点什么
                currentAngleBaseLatestStart,
                latestAngle
              });
              showTopAndBottomText('xx.xx %', '路径错误');
              canvas.removeEventListener('mousemove', onMouseMove)
            } else {
              const percent = calculateDispersal(distance);

              showTopAndBottomText('完美圆形：'+percent.toFixed(2) + ' %', ' ');
            }
            latestAngle = currentAngleBaseLatestStart;

          }


          ctx.lineTo(dotx, doty);
          ctx.stroke();
          path.points.push({ x: dotx, y: doty });


          // 计算角度
          currentAngle = calcCircleAngle(path.points, canvasCenterX, canvasCenterY)
          console.log('===currentAngle', currentAngle);


          console.log('====当前距离：', a1);
          if (currentAngle > 360) {
            console.log('一个圆');
            const percent = calculateDispersal(distance);
            if (best < percent) {// 记录最好成绩
              best = percent;
              bottom2Text('最好成绩：' + best.toFixed(2) + ' %')
            }
            canvas.removeEventListener('mousemove', onMouseMove)
          }
        }

        function onMouseUp() {
          canvas.removeEventListener('mousemove', onMouseMove);
          canvas.removeEventListener('mouseup', onMouseUp);
        }
      });



      forceUpdate({})
    }
  }, []);

  // @ts-ignore
  window.__ctx = ctxRef.current;

  return (
    <div style={{
      width: width,
      height: height,
      position: 'relative'
    }}>
      <canvas style={{
        border: '1px solid',
        width: width,
        height: height,
      }}
        // 由于style中的宽高实际上是算上了dpr的，所以这里画布的宽高也要算上dpr
        width={Math.round(width * dpr)}
        height={Math.round(height * dpr)}
        ref={canvasRef} id="draw_circle_canvas" />

      <div
        id='show_error'
        hidden={false}
        style={{
          pointerEvents: 'none',
          position: 'absolute',
          left: width / 2,
          top: height / 2,
          textAlign: 'center',
          transform: 'translate(-50%, -50%)',
          userSelect: 'none',
          MozUserSelect: 'none',
          MozUserFocus: 'none',
          WebkitUserSelect: 'none',
          whiteSpace: 'pre',
        }}>
        <div >
          围绕圆点画个圆吧
        </div>
        <div
          style={{
            fontSize: '26px',
            color: 'blue',
          }}

          id='result'>
          {/* xx.xx % */}
          {' '}
        </div>
        <div style={{
          height: '30px'
        }}>

        </div>
        <div id='error_text'>
          {/* 路径错误 等下方的错误提示 */}
          {' '}
        </div>
        <div id='best'>
          {' '}
        </div>
      </div>
    </div>
  );
}

/** 给一个canvas元素画出坐标轴 */
function drawGrid(canvas: HTMLCanvasElement, grid: number = 100) {
  // canvas是由一个一个像素组成的，而0,0坐标是在第一个像素方块的左上角，并不是正中心。
  const offset = 0.5;
  const ctx = canvas.getContext('2d')!

  // ctx.beginPath();
  // let start1 = 2.5
  // ctx.moveTo(start1, 0);
  // ctx.lineTo(start1, 120);
  // ctx.stroke();
  // ctx.closePath();


  // ctx.beginPath();
  // let start2 = 6
  // ctx.moveTo(start2, 0);
  // ctx.lineTo(start2, 120);
  // ctx.stroke();
  // ctx.closePath();




  const height = canvas.height;
  const width = canvas.width
  console.log({
    height,
    width
  })
  const rawCount = Math.floor(height / grid);
  const colCount = Math.floor(width / grid);
  ctx.lineWidth = 1;
  ctx.strokeStyle = 'black' //'rgb(220, 238, 254)'
  ctx?.beginPath();
  ctx.textAlign = 'start'
  ctx.font = '16px Arial';
  let x = 0, y = 0;
  for (let r = 0; r <= rawCount; r++) {
    y = r * grid;

    // console.log('rrr', x, y);
    ctx.fillText(String(y), 0, y + offset);
    if (y === 0) {
      continue;
    }
    ctx.moveTo(0, y + offset);
    ctx.lineTo(width, y + offset);
  }

  for (let c = 0; c <= colCount; c++) {
    x = c * grid;

    ctx.fillText(String(x), x + offset + 2, 14);
    if (x === 0) {
      continue;
    }
    ctx.moveTo(x + offset, 0);
    ctx.lineTo(x + offset, height);
  }
  ctx.stroke();

  ctx.closePath();
}

/** 画中心圆点 */
function drawCenter(canvas: HTMLCanvasElement) {
  const ctx = canvas.getContext('2d');
  if (ctx) {
    ctx.beginPath();
    ctx.textAlign = 'center';
    ctx.fillStyle = 'gray';
    // ctx.font = '16px Arial grey'
    // ctx.fillText('围绕中心点画圆', canvas.width / 2, canvas.height / 2 - 14)
    ctx?.arc(canvas.width / 2, canvas.height / 2, 6, 0, Math.PI * 2);
    ctx.fill();
    ctx.closePath();
  }
}

/** 计算2个坐标点的距离 */
function calculateDistance(x1: number, y1: number, x2: number, y2: number) {
  return Math.sqrt(Math.pow(x2 - x1, 2) + Math.pow(y2 - y1, 2));
}


