// 计算两个向量的夹角(0-180 单位：角度）
function calculateAngle(x1: number, y1: number, xo1: number, yo1: number, x2: number, y2: number) {
  // 计算向量1
  let vector1x = x1 - xo1;
  let vector1y = y1 - yo1;

  // 计算向量2
  let vector2x = x2 - xo1;
  let vector2y = y2 - yo1;

  // 计算向量1和向量2的点积
  let dotProduct = vector1x * vector2x + vector1y * vector2y;

  // 计算向量1和向量2的模
  let magnitude1 = Math.sqrt(vector1x * vector1x + vector1y * vector1y);
  let magnitude2 = Math.sqrt(vector2x * vector2x + vector2y * vector2y);

  // 计算夹角的余弦值
  let cosAngle = dotProduct / (magnitude1 * magnitude2);

  // 计算夹角（弧度）
  let angle = Math.acos(cosAngle);

  // 将弧度转换为角度
  let degrees = angle * (180 / Math.PI);

  return degrees;
}



/**
 * 取圆周路径上的8个点，将这些点与xy组成向量，计算这8个向量的夹角总和
 * @param path 圆周路径上的点坐标 
 * @param x 圆心x
 * @param y 圆心y
 */
function calcCircleAngle(path: { x: number, y: number }[], x: number, y: number) {
  const step = Math.floor(path.length / 8) || 1;
  let angle = 0;
  for (let index = 0; index < path.length; index += step) {
    const p1 = path[index];
    const p2 = path[index + step] || path[path.length - 1];
    angle += calculateAngle(p1.x, p1.y, x, y, p2.x, p2.y);
  }

  return angle;
}


/** 展示分数和错误信息*/
function showTopAndBottomText(topText: string, bottomText: string) {
  document.getElementById('show_error')!.hidden = false;
  document.getElementById('result')!.innerText = topText || ' '
  document.getElementById('error_text')!.innerText = bottomText || ' '
}

/** 关闭显示分数和错误信息 */
function hiddenError() {
  document.getElementById('show_error')!.hidden = true;
}

/** 计算一组数字的离散程度 */
function calculateDispersal(data: number[]) {
  // 计算均值
  const mean = data.reduce((acc, val) => acc + val, 0) / data.length;

  // 计算方差
  const variance = data.reduce((acc, val) => acc + Math.pow(val - mean, 2), 0) / data.length;

  // 计算标准差
  const stdDev = Math.sqrt(variance);

  // 计算标准差与均值的比率
  const dispersalPercentage = (stdDev / mean) * 100;

  return (100 - dispersalPercentage);
}

function bottom2Text(str: string) {
  document.getElementById('best')!.innerText = str || ' '
}